window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7d9ebc39085cfe3c"]={"versions": [{"id": "FIG-7d9ebc39085cfe3c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsparametersatzes (ECUC) für das FlexRay Interface (<code>FrIf</code>). Es spezifiziert die Metamodellstruktur der Konfigurationscontainer, Subcontainer und Parameter innerhalb des AUTOSAR-BAP-/Kommunikationsstacks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modul <code>FrIf</code> (<code>EcucModuleDef</code>, Kardinalität 0..1) aggregiert als Container:</p>\n<ul class=\"fig-list\">\n<li><code>FrIfGeneral</code> (<code>EcucParamConfContainerDef</code>)</li>\n<li><code>FrIfConfig</code> (<code>EcucParamConfContainerDef</code>, <code>multipleConfigurationContainer = true</code>), welches wiederum aggregiert:</li>\n<li><code>FrIfFrameStructure</code> (<code>EcucParamConfContainerDef</code>, 1..\\<em>), aggregiert <code>FrIfPdusInFrame</code> (<code>EcucParamConfContainerDef</code>, 1..\\</em>)</li>\n<li><code>FrIfPdu</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert <code>FrIfPduDirection</code> (<code>EcucChoiceContainerDef</code>), welches die Wahl zwischen <code>FrIfRxPdu</code> (0..1) und <code>FrIfTxPdu</code> (0..1) bietet</li>\n<li><code>FrIfCluster</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert:</li>\n<li><code>FrIfJobList</code> (<code>EcucParamConfContainerDef</code>), aggregiert <code>FrIfJob</code> (<code>EcucParamConfContainerDef</code>, 1..\\*)</li>\n<li><code>FrIfController</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert:</li>\n<li><code>FrIfTransceiver</code> (<code>EcucParamConfContainerDef</code>, 1..2)</li>\n<li><code>FrIfFrameTriggering</code> (<code>EcucParamConfContainerDef</code>, 1..\\*)</li>\n<li><code>FrIfLPdu</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), welches den Parameter <code>FrIfLPduIdx</code> (<code>EcucIntegerParamDef</code>, <code>symbolicNameValue = true</code>, <code>max = 4095</code>) enthält.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell definiert das Diagramm keine Laufzeitsequenzen. Die Hierarchie bildet die Dekodierungs- und Verarbeitungsreihenfolge für das FlexRay-Interface ab: Ein Cluster bindet Controller und Jobs; Controller verwalten Transceiver, Frame-Triggering und LPdus; Konfigurationen referenzieren Frame-Strukturen und PDU-Zuordnungen für RX und TX.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die ECUC-Schemadefinition des FrIf-Moduls. Generatoren müssen die vorgegebenen Multiplizitäten validieren (z. B. mindestens 1 Controller, Cluster, FrameStructure, Pdu, Job, LPdu sowie 1 bis 2 Transceiver je Controller). <code>FrIfConfig</code> ist als multipler Konfigurationscontainer für Post-Build-Variantenbildung vorgesehen.</p>"}, {"id": "FIG-c466bfda00e27bee", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsparametersatzes (ECUC) für das FlexRay Interface (<code>FrIf</code>). Es spezifiziert die Metamodellstruktur der Konfigurationscontainer, Subcontainer und Parameter innerhalb des AUTOSAR-BAP-/Kommunikationsstacks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modul <code>FrIf</code> (<code>EcucModuleDef</code>, Kardinalität 0..1) aggregiert als Container:</p>\n<ul class=\"fig-list\">\n<li><code>FrIfGeneral</code> (<code>EcucParamConfContainerDef</code>)</li>\n<li><code>FrIfConfig</code> (<code>EcucParamConfContainerDef</code>, <code>multipleConfigurationContainer = true</code>), welches aggregiert:</li>\n<li>Parameter <code>FrIfMaxPduCnt</code> (<code>EcucIntegerParamDef</code>, 0..1)</li>\n<li><code>FrIfFrameStructure</code> (<code>EcucParamConfContainerDef</code>, 1..\\<em>, <code>postBuildChangeable = true</code>), aggregiert <code>FrIfPdusInFrame</code> (<code>EcucParamConfContainerDef</code>, 1..\\</em>, <code>postBuildChangeable = true</code>)</li>\n<li><code>FrIfPdu</code> (<code>EcucParamConfContainerDef</code>, 1..\\*, <code>postBuildChangeable = true</code>), aggregiert <code>FrIfPduDirection</code> (<code>EcucChoiceContainerDef</code>), welches die Auswahl zwischen <code>FrIfRxPdu</code> (0..1) und <code>FrIfTxPdu</code> (0..1) bereitstellt</li>\n<li><code>FrIfCluster</code> (<code>EcucParamConfContainerDef</code>, 1..\\*, <code>postBuildChangeable = false</code>), aggregiert:</li>\n<li><code>FrIfJobList</code> (<code>EcucParamConfContainerDef</code>), aggregiert <code>FrIfJob</code> (<code>EcucParamConfContainerDef</code>, 1..\\*, <code>postBuildChangeable = true</code>)</li>\n<li><code>FrIfController</code> (<code>EcucParamConfContainerDef</code>, 1..\\*, <code>postBuildChangeable = false</code>), aggregiert:</li>\n<li><code>FrIfTransceiver</code> (<code>EcucParamConfContainerDef</code>, 1..2)</li>\n<li><code>FrIfFrameTriggering</code> (<code>EcucParamConfContainerDef</code>, 1..\\*)</li>\n<li><code>FrIfLPdu</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert den Parameter <code>FrIfLPduIdx</code> (<code>EcucIntegerParamDef</code>, <code>symbolicNameValue = true</code>, <code>max = 4095</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell definiert das Diagramm keine Laufzeitsequenzen. Die Hierarchie bildet die Dekodierungs- und Verarbeitungsreihenfolge für das FlexRay-Interface ab: Ein Cluster bindet Controller und Jobs; Controller verwalten Transceiver, Frame-Triggering und LPdus; Konfigurationen referenzieren Frame-Strukturen und PDU-Zuordnungen für RX und TX.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die ECUC-Schemadefinition des FrIf-Moduls. Konfigurationswerkzeuge und BSW-Generatoren müssen die <code>postBuildChangeable</code>-Flags beachten: Cluster- und Controller-Definitionen sind zur Laufzeit unveränderlich (<code>postBuildChangeable = false</code>), während Frame-Strukturen, PDUs, Jobs und PDUs in Frames als Post-Build-änderbar (<code>postBuildChangeable = true</code>) ausgelegt sind. <code>FrIfMaxPduCnt</code> begrenzt optional die maximale PDU-Anzahl.</p>"}, {"id": "FIG-d9380f876f355252", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsparametersatzes (ECUC) für das FlexRay Interface (<code>FrIf</code>). Es spezifiziert die Metamodellstruktur der Konfigurationscontainer, Subcontainer und Parameter innerhalb des AUTOSAR-BAP-/Kommunikationsstacks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modul <code>FrIf</code> (<code>EcucModuleDef</code>, Kardinalität 0..1) aggregiert als Container:</p>\n<ul class=\"fig-list\">\n<li><code>FrIfGeneral</code> (<code>EcucParamConfContainerDef</code>)</li>\n<li><code>FrIfConfig</code> (<code>EcucParamConfContainerDef</code>), welches aggregiert:</li>\n<li>Parameter <code>FrIfMaxPduCnt</code> (<code>EcucIntegerParamDef</code>, 0..1)</li>\n<li><code>FrIfFrameStructure</code> (<code>EcucParamConfContainerDef</code>, 1..\\<em>), aggregiert <code>FrIfPdusInFrame</code> (<code>EcucParamConfContainerDef</code>, 1..\\</em>)</li>\n<li><code>FrIfPdu</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert <code>FrIfPduDirection</code> (<code>EcucChoiceContainerDef</code>), welches die Auswahl zwischen <code>FrIfRxPdu</code> (0..1) und <code>FrIfTxPdu</code> (0..1) bereitstellt</li>\n<li><code>FrIfCluster</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert:</li>\n<li><code>FrIfJobList</code> (<code>EcucParamConfContainerDef</code>), aggregiert <code>FrIfJob</code> (<code>EcucParamConfContainerDef</code>, 1..\\*)</li>\n<li><code>FrIfController</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert:</li>\n<li><code>FrIfTransceiver</code> (<code>EcucParamConfContainerDef</code>, 1..2)</li>\n<li><code>FrIfFrameTriggering</code> (<code>EcucParamConfContainerDef</code>, 1..\\*)</li>\n<li><code>FrIfLPdu</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert den Parameter <code>FrIfLPduIdx</code> (<code>EcucIntegerParamDef</code>, <code>symbolicNameValue = true</code>, <code>max = 4095</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell definiert das Diagramm keine Laufzeitsequenzen. Die Hierarchie bildet die Dekodierungs- und Verarbeitungsreihenfolge für das FlexRay-Interface ab: Ein Cluster bindet Controller und Jobs; Controller verwalten Transceiver, Frame-Triggering und LPdus; Konfigurationen referenzieren Frame-Strukturen und PDU-Zuordnungen für RX und TX.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die ECUC-Schemadefinition des FrIf-Moduls. Generatoren müssen die vorgegebenen Multiplizitäten validieren (u. a. 1..\\* für Controller, Cluster, FrameStructure, Pdu, Job, LPdu sowie 1..2 für Transceiver). Post-Build-Änderbarkeitsattribute sind im Diagramm nicht mehr explizit annotiert; <code>FrIfConfig</code> fungiert als Standard-Parametercontainer.</p>"}, {"id": "FIG-424df9a39ea3e672", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsparametersatzes (ECUC) für das FlexRay Interface (<code>FrIf</code>). Es spezifiziert die Metamodellstruktur der Konfigurationscontainer, Subcontainer und Parameter innerhalb des AUTOSAR-BAP-/Kommunikationsstacks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modul <code>FrIf</code> (<code>EcucModuleDef</code>, Kardinalität 0..1) aggregiert als Container:</p>\n<ul class=\"fig-list\">\n<li><code>FrIfGeneral</code> (<code>EcucParamConfContainerDef</code>)</li>\n<li><code>FrIfConfig</code> (<code>EcucParamConfContainerDef</code>), welches aggregiert:</li>\n<li>Parameter <code>FrIfMaxPduCnt</code> (<code>EcucIntegerParamDef</code>, 0..1)</li>\n<li><code>FrIfFrameStructure</code> (<code>EcucParamConfContainerDef</code>, 1..\\<em>), aggregiert <code>FrIfPdusInFrame</code> (<code>EcucParamConfContainerDef</code>, 1..\\</em>)</li>\n<li><code>FrIfPdu</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert <code>FrIfPduDirection</code> (<code>EcucChoiceContainerDef</code>), welches die Auswahl zwischen <code>FrIfRxPdu</code> (0..1) und <code>FrIfTxPdu</code> (0..1) bereitstellt</li>\n<li><code>FrIfCluster</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert:</li>\n<li><code>FrIfJobList</code> (<code>EcucParamConfContainerDef</code>), aggregiert <code>FrIfJob</code> (<code>EcucParamConfContainerDef</code>, 1..\\*)</li>\n<li><code>FrIfController</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert:</li>\n<li><code>FrIfTransceiver</code> (<code>EcucParamConfContainerDef</code>, 1..2)</li>\n<li><code>FrIfFrameTriggering</code> (<code>EcucParamConfContainerDef</code>, 1..\\*)</li>\n<li><code>FrIfLPdu</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert den Parameter <code>FrIfLPduIdx</code> (<code>EcucIntegerParamDef</code>, <code>symbolicNameValue = true</code>, <code>max = 4095</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell definiert das Diagramm keine Laufzeitsequenzen. Die Hierarchie bildet die Dekodierungs- und Verarbeitungsreihenfolge für das FlexRay-Interface ab: Ein Cluster bindet Controller und Jobs; Controller verwalten Transceiver, Frame-Triggering und LPdus; Konfigurationen referenzieren Frame-Strukturen und PDU-Zuordnungen für RX und TX.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die ECUC-Schemadefinition des FrIf-Moduls. Generatoren müssen die vorgegebenen Multiplizitäten validieren (u. a. 1..\\* für Controller, Cluster, FrameStructure, Pdu, Job, LPdu sowie 1..2 für Transceiver). Post-Build-Änderbarkeitsattribute sind im Diagramm nicht mehr explizit annotiert; <code>FrIfConfig</code> fungiert als Standard-Parametercontainer.</p>"}, {"id": "FIG-98006ca8d26f7f24", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsparametersatzes (ECUC) für das FlexRay Interface (<code>FrIf</code>). Es spezifiziert die Metamodellstruktur der Konfigurationscontainer, Subcontainer und Parameter innerhalb des AUTOSAR-BAP-/Kommunikationsstacks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modul <code>FrIf</code> (<code>EcucModuleDef</code>, Kardinalität 0..1) aggregiert als Container:</p>\n<ul class=\"fig-list\">\n<li><code>FrIfGeneral</code> (<code>EcucParamConfContainerDef</code>)</li>\n<li><code>FrIfConfig</code> (<code>EcucParamConfContainerDef</code>), welches aggregiert:</li>\n<li>Parameter <code>FrIfMaxPduCnt</code> (<code>EcucIntegerParamDef</code>, 0..1)</li>\n<li><code>FrIfFrameStructure</code> (<code>EcucParamConfContainerDef</code>, 1..\\<em>), aggregiert <code>FrIfPdusInFrame</code> (<code>EcucParamConfContainerDef</code>, 1..\\</em>)</li>\n<li><code>FrIfPdu</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert <code>FrIfPduDirection</code> (<code>EcucChoiceContainerDef</code>), welches die Auswahl zwischen <code>FrIfRxPdu</code> (0..1) und <code>FrIfTxPdu</code> (0..1) bereitstellt</li>\n<li><code>FrIfCluster</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert:</li>\n<li><code>FrIfJobList</code> (<code>EcucParamConfContainerDef</code>), aggregiert <code>FrIfJob</code> (<code>EcucParamConfContainerDef</code>, 1..\\*)</li>\n<li><code>FrIfController</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert:</li>\n<li><code>FrIfTransceiver</code> (<code>EcucParamConfContainerDef</code>, 1..2)</li>\n<li><code>FrIfFrameTriggering</code> (<code>EcucParamConfContainerDef</code>, 1..\\*)</li>\n<li><code>FrIfLPdu</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert den Parameter <code>FrIfLPduIdx</code> (<code>EcucIntegerParamDef</code>, <code>symbolicNameValue = true</code>, <code>min = 0</code>, <code>max = 4095</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell definiert das Diagramm keine Laufzeitsequenzen. Die Hierarchie bildet die Dekodierungs- und Verarbeitungsreihenfolge für das FlexRay-Interface ab: Ein Cluster bindet Controller und Jobs; Controller verwalten Transceiver, Frame-Triggering und LPdus; Konfigurationen referenzieren Frame-Strukturen und PDU-Zuordnungen für RX und TX.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die ECUC-Schemadefinition des FrIf-Moduls. Generatoren müssen für <code>FrIfLPduIdx</code> den Wertebereich <code>[0..4095]</code> sowie die Eigenschaft als symbolischer Name (<code>symbolicNameValue = true</code>) sicherstellen und die Multiplizitäten aller Subcontainer validieren.</p>"}, {"id": "FIG-0bd46d1392ca6fa0", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsparametersatzes (ECUC) für das FlexRay Interface (<code>FrIf</code>). Es spezifiziert die Metamodellstruktur der Konfigurationscontainer, Subcontainer und Parameter innerhalb des AUTOSAR-BAP-/Kommunikationsstacks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modul <code>FrIf</code> (<code>EcucModuleDef</code>, Kardinalität 0..1) aggregiert als Container:</p>\n<ul class=\"fig-list\">\n<li><code>FrIfGeneral</code> (<code>EcucParamConfContainerDef</code>)</li>\n<li><code>FrIfConfig</code> (<code>EcucParamConfContainerDef</code>), welches aggregiert:</li>\n<li>Parameter <code>FrIfMaxPduCnt</code> (<code>EcucIntegerParamDef</code>, 0..1)</li>\n<li><code>FrIfFrameStructure</code> (<code>EcucParamConfContainerDef</code>, 1..\\<em>), aggregiert <code>FrIfPdusInFrame</code> (<code>EcucParamConfContainerDef</code>, 1..\\</em>)</li>\n<li><code>FrIfPdu</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert <code>FrIfPduDirection</code> (<code>EcucChoiceContainerDef</code>), welches die Auswahl zwischen <code>FrIfRxPdu</code> (0..1) und <code>FrIfTxPdu</code> (0..1) bereitstellt</li>\n<li><code>FrIfCluster</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert:</li>\n<li><code>FrIfJobList</code> (<code>EcucParamConfContainerDef</code>), aggregiert <code>FrIfJob</code> (<code>EcucParamConfContainerDef</code>, 1..\\*)</li>\n<li><code>FrIfController</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert:</li>\n<li><code>FrIfTransceiver</code> (<code>EcucParamConfContainerDef</code>, 1..2)</li>\n<li><code>FrIfFrameTriggering</code> (<code>EcucParamConfContainerDef</code>, 1..\\*)</li>\n<li><code>FrIfLPdu</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert den Parameter <code>FrIfLPduIdx</code> (<code>EcucIntegerParamDef</code>, <code>symbolicNameValue = true</code>, <code>min = 0</code>, <code>max = 4095</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell definiert das Diagramm keine Laufzeitsequenzen. Die Hierarchie bildet die Dekodierungs- und Verarbeitungsreihenfolge für das FlexRay-Interface ab: Ein Cluster bindet Controller und Jobs; Controller verwalten Transceiver, Frame-Triggering und LPdus; Konfigurationen referenzieren Frame-Strukturen und PDU-Zuordnungen für RX und TX.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die ECUC-Schemadefinition des FrIf-Moduls. Generatoren müssen für <code>FrIfLPduIdx</code> den Wertebereich <code>[0..4095]</code> sowie die Eigenschaft als symbolischer Name (<code>symbolicNameValue = true</code>) sicherstellen und die Multiplizitäten aller Subcontainer validieren.</p>"}, {"id": "FIG-d17009f391ee886e", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsparametersatzes (ECUC) für das FlexRay Interface (<code>FrIf</code>). Es spezifiziert die Metamodellstruktur der Konfigurationscontainer, Subcontainer und Parameter innerhalb des AUTOSAR-BAP-/Kommunikationsstacks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modul <code>FrIf</code> (<code>EcucModuleDef</code>, Kardinalität 0..1) aggregiert als Container:</p>\n<ul class=\"fig-list\">\n<li><code>FrIfGeneral</code> (<code>EcucParamConfContainerDef</code>)</li>\n<li><code>FrIfConfig</code> (<code>EcucParamConfContainerDef</code>), welches aggregiert:</li>\n<li>Parameter <code>FrIfMaxPduCnt</code> (<code>EcucIntegerParamDef</code>, 0..1)</li>\n<li><code>FrIfFrameStructure</code> (<code>EcucParamConfContainerDef</code>, 1..\\<em>), aggregiert <code>FrIfPdusInFrame</code> (<code>EcucParamConfContainerDef</code>, 1..\\</em>)</li>\n<li><code>FrIfPdu</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert <code>FrIfPduDirection</code> (<code>EcucChoiceContainerDef</code>), welches die Auswahl zwischen <code>FrIfRxPdu</code> (0..1) und <code>FrIfTxPdu</code> (0..1) bereitstellt</li>\n<li><code>FrIfCluster</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert:</li>\n<li><code>FrIfJobList</code> (<code>EcucParamConfContainerDef</code>), aggregiert <code>FrIfJob</code> (<code>EcucParamConfContainerDef</code>, 1..\\*)</li>\n<li><code>FrIfController</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert:</li>\n<li><code>FrIfTransceiver</code> (<code>EcucParamConfContainerDef</code>, 1..2)</li>\n<li><code>FrIfFrameTriggering</code> (<code>EcucParamConfContainerDef</code>, 1..\\*)</li>\n<li><code>FrIfLPdu</code> (<code>EcucParamConfContainerDef</code>, 1..\\*), aggregiert den Parameter <code>FrIfLPduIdx</code> (<code>EcucIntegerParamDef</code>, <code>symbolicNameValue = true</code>, <code>min = 0</code>, <code>max = 4095</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell definiert das Diagramm keine Laufzeitsequenzen. Die Hierarchie bildet die Dekodierungs- und Verarbeitungsreihenfolge für das FlexRay-Interface ab: Ein Cluster bindet Controller und Jobs; Controller verwalten Transceiver, Frame-Triggering und LPdus; Konfigurationen referenzieren Frame-Strukturen und PDU-Zuordnungen für RX und TX.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die ECUC-Schemadefinition des FrIf-Moduls. Generatoren müssen für <code>FrIfLPduIdx</code> den Wertebereich <code>[0..4095]</code> sowie die Eigenschaft als symbolischer Name (<code>symbolicNameValue = true</code>) sicherstellen und die Multiplizitäten aller Subcontainer validieren.</p>"}], "trans": [{"from": "FIG-7d9ebc39085cfe3c", "to": "FIG-c466bfda00e27bee", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>FrIfConfig</code>: Neuer Parameter <code>+parameter</code> <code>FrIfMaxPduCnt: EcucIntegerParamDef</code> mit <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>FrIfController</code>: Attribut <code>postBuildChangeable = false</code> hinzugefügt.</li>\n<li><code>FrIfCluster</code>: Attribut <code>postBuildChangeable = false</code> hinzugefügt.</li>\n<li><code>FrIfFrameStructure</code>: Attribut <code>postBuildChangeable = true</code> hinzugefügt.</li>\n<li><code>FrIfPdusInFrame</code>: Attribut <code>postBuildChangeable = true</code> hinzugefügt.</li>\n<li><code>FrIfPdu</code>: Attribut <code>postBuildChangeable = true</code> hinzugefügt.</li>\n<li><code>FrIfJob</code>: Attribut <code>postBuildChangeable = true</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-c466bfda00e27bee", "to": "FIG-d9380f876f355252", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>FrIfConfig</code>: Attribut <code>multipleConfigurationContainer = true</code> entfernt.</li>\n<li><code>FrIfController</code>: Attribut <code>postBuildChangeable = false</code> entfernt.</li>\n<li><code>FrIfCluster</code>: Attribut <code>postBuildChangeable = false</code> entfernt.</li>\n<li><code>FrIfFrameStructure</code>: Attribut <code>postBuildChangeable = true</code> entfernt.</li>\n<li><code>FrIfPdusInFrame</code>: Attribut <code>postBuildChangeable = true</code> entfernt.</li>\n<li><code>FrIfPdu</code>: Attribut <code>postBuildChangeable = true</code> entfernt.</li>\n<li><code>FrIfJob</code>: Attribut <code>postBuildChangeable = true</code> entfernt.</li>\n</ul>"}, {"from": "FIG-d9380f876f355252", "to": "FIG-424df9a39ea3e672", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-424df9a39ea3e672", "to": "FIG-98006ca8d26f7f24", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>FrIfLPduIdx</code>: Attribute <code>symbolicNameValue = true</code> und <code>min = 0</code> hinzugefügt (neben dem bestehenden <code>max = 4095</code>).</li>\n<li>Typografische Vereinheitlichung aller Klassennamen: Leerzeichen vor dem Doppelpunkt entfernt (z. B. <code>FrIf: EcucModuleDef</code> statt <code>FrIf :EcucModuleDef</code>).</li>\n</ul>"}, {"from": "FIG-98006ca8d26f7f24", "to": "FIG-0bd46d1392ca6fa0", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0bd46d1392ca6fa0", "to": "FIG-d17009f391ee886e", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
